import heapq

def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    idx = {t: i for i, t in enumerate(coords)}
    n = len(coords)

    # Graph: [to, cap, cost, rev_idx]
    adj = [[] for _ in range(n)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for s, e, pay in jobs:
        add_edge(idx[s], idx[e], 1, -pay)

    # Initial potentials via DAG shortest path (all forward edges have u < v)
    INF = 10**18
    pot = [INF] * n
    pot[0] = 0
    for u in range(n):
        if pot[u] == INF:
            continue
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and pot[u] + cost < pot[v]:
                pot[v] = pot[u] + cost

    total_cost = 0
    sink = n - 1

    for _ in range(k):
        dist = [INF] * n
        parent_v = [-1] * n
        parent_e = [-1] * n
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pot[u] - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == INF:
            break

        for i in range(n):
            if dist[i] < INF:
                pot[i] += dist[i]

        if pot[sink] >= 0:
            break

        total_cost += pot[sink]

        v = sink
        while v != 0:
            u = parent_v[v]
            ei = parent_e[v]
            edge = adj[u][ei]
            edge[1] -= 1
            adj[v][edge[3]][1] += 1
            v = u

    return -total_cost
